mapper.select:
SELECT DISTINCT category_id from article
where category_id in

    #{id}

SELECT a.id, a.title, a.summary, a.content, a.category_id, a.cover, a.status, a.is_top, a.is_hot, a.view_num, a.like_num, a.comment_num, a.words_num, a.create_time, a.update_time, a.publish_time, a.timed_publish_time, a.user_id, a.sort, u.nickname AS user_nickname, u.avatar AS user_avatar, c.name AS category_name, ( SELECT GROUP_CONCAT(t.id SEPARATOR ',') FROM tag t INNER JOIN article_tag at ON t.id = at.tag_id WHERE at.article_id = a.id ) AS tags_str from article a LEFT JOIN sys_user u ON a.user_id = u.id LEFT JOIN category c ON a.category_id = c.id
AND a.title LIKE CONCAT('%', #{title}, '%')
AND c.id = #{categoryId}
AND a.id IN ( SELECT at.article_id FROM article_tag at INNER JOIN tag t ON at.tag_id = t.id WHERE t.name = #{tag} )
AND a.status = #{status}
AND a.is_top = #{isTop}
AND a.publish_time BETWEEN #{begin} AND #{end}
ORDER BY a.is_top DESC, a.publish_time DESC

